import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy player flow","description":"October 23, 2026. Sherwin owns the experience; Christian owns behavior; Miguel owns screens. Follow the canonical GDD. This is the November 10 core; teacher enrollment and ful","frontmatter":{"title":"Chainy player flow","description":"October 23, 2026. Sherwin owns the experience; Christian owns behavior; Miguel owns screens. Follow the canonical GDD. This is the November 10 core; teacher enrollment and ful","source":"docs/design/app-flow.md","category":"Game & system design","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/app-flow.md","filePath":"content/docs/design/app-flow.md"}'),n={name:"content/docs/design/app-flow.md"};function i(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<div><h1 id="chainy-player-flow">Chainy player flow<a class="header-anchor" href="#chainy-player-flow" aria-label="Link to this section">​</a></h1><p>October 23, 2026. Sherwin owns the experience; Christian owns behavior; Miguel owns screens. Follow the <a href="/Chainy-Docs/content/docs/game-design.html">canonical GDD</a>. This is the November 10 core; teacher enrollment and full-world expansion are later gates.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  A[Open offline game] --&gt; B[Select local demo profile]
  B --&gt; C[Load SQLite checkpoint]
  C --&gt; D[Explore and inspect quest log]
  D --&gt; E[Interact and read live-world dialogue]
  E --&gt; F[W01-W04 wallet, reward, purchase and restore]
  F --&gt; G[B01-B03 inspect and repair same record]
  G --&gt; H[Demo B07 restore beacon]
  H --&gt; I[Demo chapter complete / revisit]
  E --&gt; J[Contextual question and explanation]
  J --&gt; D
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><h2 id="state-and-recovery-contract">State and recovery contract<a class="header-anchor" href="#state-and-recovery-contract" aria-label="Link to this section">​</a></h2><table><thead><tr><th>State</th><th>Player behavior and invariant</th></tr></thead><tbody><tr><td>Startup/profile</td><td>Validate versions and load the selected profile before play. Preserve existing data on failure; a local code is not authentication.</td></tr><tr><td>Exploration/dialogue</td><td>Move and interact; dialogue remains over the live 3D world and blocks world input. Restore controls and focus when it closes.</td></tr><tr><td>Quest</td><td>Locked → available → active → ready to report → completed. Retain early pickups; prevent duplicate rewards and invalid prerequisite bypasses.</td></tr><tr><td>Wallet review</td><td>Show item, price 8, fee 1 and total 9 before authorization. Cancellation costs nothing. No real payment or secret is requested.</td></tr><tr><td>Authorization/pending</td><td>Accept one command. Lock duplicate taps; do not show confirmed ownership before the atomic save succeeds.</td></tr><tr><td>Confirmed/save error</td><td>Balance, inventory, ledger and quest state change together or not at all. Retry the same operation without duplicate charge or reward.</td></tr><tr><td>Blockchain repair</td><td>Inspect the original transaction/checkpoint and validate three linked blocks; explain why an altered record is rejected.</td></tr><tr><td>Journal/encyclopedia</td><td>Show current objective, chronological progress and evidence labels, not an unsupported mastery percentage.</td></tr><tr><td>Pause/back/switch</td><td>Resolve pending operations, clear prior profile state and return to a usable screen. Define checkpoint resume; do not promise mid-animation recovery.</td></tr><tr><td>Chapter completion</td><td>Label the demo chapter complete. Full Web3 → Blockchain → AI world unlocks are not implied by a core-only build.</td></tr></tbody></table><p>Christian defines the internal interfaces and persistence transaction boundaries; Miguel presents returned state without implementing rules or SQL. Sean authors approved copy. AI training/practice/final-test panels are conditional stretch. Wordle, BlockMatch and teacher-service screens are outside the beta core.</p></div>`,1)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
